import math


def prod_Square(n):
    """Write a python function to check whether the given number can be represented by product of two squares or not.

    Return ``True`` exactly when ``n == a * a * b * b`` for integers
    ``a`` and ``b`` that are both greater than 1. The squares must be
    greater than 1: allowing ``1`` would make every perfect square,
    including 25, trivially qualify, contrary to the example in the
    issue. Hence ``n`` must be the square of a composite number.
    """
    if n <= 1:
        return False

    root = math.isqrt(n)
    if root * root != n:
        return False

    # ``root`` must be composite, i.e. have a divisor strictly between
    # 1 and itself, so that it can be split as ``root == a * b`` with
    # both factors greater than 1.
    for divisor in range(2, math.isqrt(root) + 1):
        if root % divisor == 0:
            return True
    return False
